-- Verificação em fonte oficial (Cartilha de Segurança para Internet, CERT.br/NIC.br, https://cartilha.cert.br/livro/cartilha-seguranca-internet.pdf) de itens da apostila de informática. Idempotente.
-- Só marca 'verificada_fonte' o que o texto da Cartilha sustenta diretamente. Os demais permanecem como estavam.
begin;
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 4.2: worm se propaga por rede, por execução de cópias ou exploração de vulnerabilidades; não é método de contornar autenticação (isso é backdoor, seção 4.5).' where apostila='Questões de informática' and numero=61 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 4.2: worm é programa que se propaga automaticamente pelas redes enviando cópias de si.' where apostila='Questões de informática' and numero=62 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seções 4.2 e 4.6: o programa com aparência atraente e função maliciosa oculta é o cavalo de troia, não o worm.' where apostila='Questões de informática' and numero=63 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 4.2: o worm não infecta outros programas como hospedeiro (diferença para o vírus).' where apostila='Questões de informática' and numero=65 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 4.2: worm é código malicioso, não programa que combate vírus.' where apostila='Questões de informática' and numero=66 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 4.3: bot é similar ao worm e possui mecanismos de controle remoto; botnet é a rede de máquinas infectadas.' where apostila='Questões de informática' and numero=67 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 4.3: bot é programa com comunicação com o invasor e propagação como a do worm; não é limitado à área de boot.' where apostila='Questões de informática' and numero=69 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 6.1: cookies são pequenos arquivos gravados no computador do usuário pelos sites visitados.' where apostila='Questões de informática' and numero=75 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 6.1: cookies são pequenos arquivos que guardam informações da navegação e têm prazo (temporário ou persistente).' where apostila='Questões de informática' and numero=76 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 9.2: hash serve para verificar a integridade de arquivo (antes e depois da transmissão).' where apostila='Questões de informática' and numero=23 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 9.2: hash serve para verificar a integridade de arquivo obtido ou transmitido.' where apostila='Questões de informática' and numero=24 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 9.2: a função de resumo gera saída de tamanho fixo para qualquer tamanho de entrada.' where apostila='Questões de informática' and numero=31 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 4.6: cavalo de troia executa funções aparentes e outras maliciosas, sem conhecimento do usuário.' where apostila='Questões de informática' and numero=110 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, seção 4.4: adware é programa projetado para apresentar propagandas.' where apostila='Questões de informática' and numero=115 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, glossário (VPN): rede privada sobre rede pública, com criptografia e outros mecanismos de segurança.' where apostila='Questões de informática' and numero=158 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, glossário (VPN): rede privada sobre rede pública, com criptografia e outros mecanismos de segurança.' where apostila='Questões de informática' and numero=175 and status='conceito_coerente';
update public.apostila_questoes_pendentes set status='verificada_fonte', note='Cartilha CERT.br, glossário (VPN): rede privada sobre rede pública, com criptografia e outros mecanismos de segurança.' where apostila='Questões de informática' and numero=180 and status='conceito_coerente';
commit;
